                    flags[k / 64] &= ~(std::uint64_t{1} << (k % 64));
                    flags[(k + step * 1) / 64] &= ~(std::uint64_t{1} << ((k + step * 1) % 64));
                    flags[(k + step * 2) / 64] &= ~(std::uint64_t{1} << ((k + step * 2) % 64));
                    flags[(k + step * 3) / 64] &= ~(std::uint64_t{1} << ((k + step * 3) % 64));
                }
                for (; k < end; k += step)
                    flags[k / 64] &= ~(std::uint64_t{1} << (k % 64));
#endif
                strikes[i].next = k;
            }
        }
        flags[0] |= (std::uint64_t{1} << 6) |
                    (std::uint64_t{1} << 8) |
                    (std::uint64_t{1} << 9) |
                    (std::uint64_t{1} << 11) |
                    (std::uint64_t{1} << 14) |
                    (std::uint64_t{1} << 15) |
                    (std::uint64_t{1} << 18) |
                    (std::uint64_t{1} << 20) |
                    (std::uint64_t{1} << 21) |
                    (std::uint64_t{1} << 23) |
                    (std::uint64_t{1} << 26) |
                    (std::uint64_t{1} << 29) |
                    (std::uint64_t{1} << 30) |
                    (std::uint64_t{1} << 33) |
                    (std::uint64_t{1} << 35) |
                    (std::uint64_t{1} << 36) |
                    (std::uint64_t{1} << 39) |
                    (std::uint64_t{1} << 41) |
                    (std::uint64_t{1} << 44) |
                    (std::uint64_t{1} << 48) |
                    (std::uint64_t{1} << 50) |
                    (std::uint64_t{1} << 51) |
                    (std::uint64_t{1} << 53) |
                    (std::uint64_t{1} << 54) |
                    (std::uint64_t{1} << 56) |
                    (std::uint64_t{1} << 63);
    }

    std::uint64_t limit_;
    std::vector<std::uint64_t> flags_;
};
#endif

