from pathlib import Path
import difflib,hashlib
p=Path(__file__).parent;s=(p/'baseline.hpp').read_text()
helper='''    // 二つの小素数の倍数を、積周期のANDマスクで同時に消す。
    template <unsigned P, unsigned Q>
#if defined(__GNUC__) || defined(__clang__)
    [[gnu::noinline]]
#endif
    static void mask_pair(std::uint64_t* flags, std::uint64_t first_word,
                          std::uint64_t word_count) noexcept {
        constexpr unsigned Period = P * Q;
        static constexpr auto pattern = [] {
            std::array<std::uint64_t, Period> result{};
            for (unsigned w = 0; w < Period; ++w) {
                std::uint64_t word = 0;
                for (unsigned bit = 0; bit < 64; ++bit) {
                    const auto n = w * 128 + bit * 2 + 1;
                    if (n % P != 0 && n % Q != 0)
                        word |= std::uint64_t{1} << bit;
                }
                result[w] = word;
            }
            return result;
        }();
        auto* dest = flags + first_word;
        auto phase = first_word % Period;
        while (phase != 0 && word_count != 0) {
            *dest++ &= pattern[phase];
            --word_count;
            if (++phase == Period) phase = 0;
        }
        while (word_count >= Period) {
            for (unsigned j = 0; j < Period; ++j) dest[j] &= pattern[j];
            dest += Period;
            word_count -= Period;
        }
        for (unsigned j = 0; j < word_count; ++j) dest[j] &= pattern[j];
    }

'''
a='    void build_blocked(std::uint64_t odds) {';assert s.count(a)==1
pairs=[(13,17),(19,23),(29,31),(37,41)]
configs={'pair13':pairs[:1],'pair3':pairs[:3],'pair4':pairs,'pair19':pairs[1:2],'pair29':pairs[2:3]}
for name,ps in configs.items():
 q=s.replace(a,helper+a)
