  anchor=f'            mask_multiples<{x}>(flags, first_word, word_count);';other=f'            mask_multiples<{y}>(flags, first_word, word_count);';assert anchor in q and other in q;q=q.replace(anchor,f'            mask_pair<{x}, {y}>(flags, first_word, word_count);').replace(other+'\n','')
