p=Path(__file__).parent;variants=['baseline','prefix_index','prefix_pointer','prefix_branchless'];builds=[];rows=[];rng=random.Random(413731)
for flags,mode in [([], 'default'),(['-march=native'],'native')]:
 for v in variants:
  cmd=['taskset','-c','8','/usr/bin/g++','-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS',*flags,'-DHEADER="'+str(p/(v+'.hpp'))+'"',str(p/'api.cpp'),'-o',str(p/(mode+'_'+v))];q=sp.run(cmd,capture_output=True,text=True);assert q.returncode==0,q.stderr;builds.append(dict(cmd=cmd,diagnostics=q.stderr,sha256=hashlib.sha256((p/(v+'.hpp')).read_bytes()).hexdigest()))
with open('/tmp/sirkit_performance_cpu4.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for n in [100000,1000000,10000000,100000000,500000000]:
  for mode in ['default','native']:
   for op in range(4):
    reps=max(2,min(10,10000000//n)) if op!=1 else max(8,min(200,100000000//n))
    for rep in range(5):
     vs=['baseline','control',*variants[1:]];rng.shuffle(vs)
     for v in vs:
      cmd=['taskset','-c','4',str(p/(mode+'_'+('baseline'if v=='control'else v))),str(n),str(op),str(reps)];q=sp.run(cmd,capture_output=True,text=True);assert q.returncode==0,q.stderr;ns,check=q.stdout.split();rows.append(dict(n=n,mode=mode,op=op,rep=rep,variant=v,reps=reps,ns=float(ns),checksum=check))
   (p/'progress.json').write_text(json.dumps(dict(builds=builds,raw=rows),indent=2));print(n,mode,flush=True)
summary=[]
for n in [100000,1000000,10000000,100000000,500000000]:
 for mode in ['default','native']:
  for op in range(4):
   rr=[x for x in rows if x['n']==n and x['mode']==mode and x['op']==op];assert len({x['checksum']for x in rr})==1
   med={v:st.median(x['ns']for x in rr if x['variant']==v)for v in ['baseline','control',*variants[1:]]};summary.append(dict(n=n,mode=mode,op=op,median_ns=med,ratio={v:t/med['baseline']for v,t in med.items()}))
(p/'results.json').write_text(json.dumps(dict(builds=builds,raw=rows,summary=summary),indent=2));print(json.dumps(summary,indent=2))

